import { MakeLogicType, actions, afterMount, connect, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { ApiError } from 'lib/api-error'
import { billingLogic } from 'scenes/billing/billingLogic'
import { organizationLogic } from 'scenes/organizationLogic'
import { teamLogic } from 'scenes/teamLogic'

import { environmentVisionQuotaRaiseLimit, environmentVisionQuotaRetrieve } from '../generated/api'
import type { VisionQuotaApi } from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface visionQuotaLogicValues {
    isAdminOrOwner: boolean | null // organizationLogic
    quota: VisionQuotaApi | null
    quotaLoading: boolean
    canRaiseCreditLimit: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface visionQuotaLogicActions {
    loadBilling: () => any // billingLogic
    adjustProjectedMonthly: (delta: number) => {
        delta: number
    }
    raiseCreditLimit: () => {
        value: true
    }
    raiseCreditLimitFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    raiseCreditLimitSuccess: (
        quota: VisionQuotaApi | null,
        payload?: {
            value: true
        }
    ) => {
        quota: VisionQuotaApi | null
        payload?: {
            value: true
        }
    }
    loadQuota: () => {
        value: true
    }
    loadQuotaFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadQuotaSuccess: (
        quota: VisionQuotaApi | null,
        payload?: {
            value: true
        }
    ) => {
        quota: VisionQuotaApi | null
        payload?: {
            value: true
        }
    }
}

export type visionQuotaLogicType = MakeLogicType<visionQuotaLogicValues, visionQuotaLogicActions>

export const visionQuotaLogic = kea<visionQuotaLogicType>([
    path(['products', 'replay_vision', 'frontend', 'logics', 'visionQuotaLogic']),

    connect(() => ({
        actions: [billingLogic, ['loadBilling']],
        values: [organizationLogic, ['isAdminOrOwner']],
    })),

    actions({
        // Declared here so the action stays zero-arg despite the loader's `breakpoint` parameter.
        loadQuota: true,
        // Optimistic shift of the fleet projection (e.g. ±scanner estimate on toggle); loadQuota reconciles.
        adjustProjectedMonthly: (delta: number) => ({ delta }),
        raiseCreditLimit: true,
    }),

    loaders(({ values }) => ({
        quota: [
            null as VisionQuotaApi | null,
            {
                loadQuota: async (_, breakpoint) => {
                    // Coalesce bursts of post-mutation refetches (e.g. toggling several scanners).
                    await breakpoint(50)
                    const teamId = teamLogic.values.currentTeamId
                    if (!teamId) {
                        return values.quota
                    }
                    try {
                        return await environmentVisionQuotaRetrieve(String(teamId))
                    } catch {
                        // Keep the last-known snapshot — nulling it would silently drop the exhausted-quota guards.
                        return values.quota
                    }
                },
                // Shares the `quota` loader so `quotaLoading` gates the trigger against double-submission
                // and the response replaces the snapshot the meters and guards read.
                raiseCreditLimit: async () => {
                    const teamId = teamLogic.values.currentTeamId
                    if (!teamId) {
                        return values.quota
                    }
                    try {
                        const quota = await environmentVisionQuotaRaiseLimit(String(teamId))
                        lemonToast.success('Budget raised. You can keep scanning.')
                        return quota
                    } catch (error) {
                        const detail = error instanceof ApiError ? error.detail : null
                        lemonToast.error(detail || "Couldn't raise your Replay vision budget. Try again.")
                        return values.quota
                    }
                },
            },
        ],
    })),

    reducers({
        quota: {
            adjustProjectedMonthly: (state: VisionQuotaApi | null, { delta }: { delta: number }) =>
                state
                    ? {
                          ...state,
                          projected_monthly_credits: Math.max(0, state.projected_monthly_credits + delta),
                      }
                    : state,
        },
    }),

    selectors({
        canRaiseCreditLimit: [
            (s) => [s.quota, s.isAdminOrOwner],
            // The API allows it and this user is senior enough to be offered it.
            (quota: VisionQuotaApi | null, isAdminOrOwner: boolean | null): boolean =>
                !!quota?.can_raise_credit_limit && !!isAdminOrOwner,
        ],
    }),

    afterMount(({ actions }) => {
        actions.loadQuota()
        // billingLogic doesn't self-load; the ingestion banner needs billing on cold navigation.
        actions.loadBilling()
    }),
])

/** Refresh after any quota-affecting mutation — observes consume quota immediately (in-flight rows count). */
export function refreshVisionQuota(): void {
    visionQuotaLogic.findMounted()?.actions.loadQuota()
}
